    @push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const panes=[...document.querySelectorAll('.nx-step-pane')],steps=[...document.querySelectorAll('.nx-step')],back=document.getElementById('companyBack'),next=document.getElementById('companyNext'),submit=document.getElementById('companySubmit');let current=0;function show(i){current=Math.max(0,Math.min(i,panes.length-1));panes.forEach((p,x)=>p.classList.toggle('active',x===current));steps.forEach((s,x)=>s.classList.toggle('active',x===current));back.disabled=!current;next.classList.toggle('d-none',current===panes.length-1);submit.classList.toggle('d-none',current!==panes.length-1)}steps.forEach((s,i)=>s.onclick=()=>show(i));back.onclick=()=>show(current-1);next.onclick=()=>{const inv=panes[current].querySelector(':invalid');if(inv){inv.reportValidity();steps[current].classList.add('error');return}show(current+1)};const list=document.getElementById('siteList');document.getElementById('addSite').onclick=()=>{const i=list.querySelectorAll('.site-card').length,node=document.getElementById('siteTemplate').content.cloneNode(true);node.querySelectorAll('[data-name]').forEach(el=>el.name=`sites[${i}][${el.dataset.name}]`);list.append(node)};list.addEventListener('click',e=>{if(e.target.closest('.remove-site'))e.target.closest('.site-card').remove()});show(0)});</script>@endpush
</x-app-layout>
